MAP
    NAME "KbS Intern Map"
    STATUS ON
    SIZE 800 600
    EXTENT 2485000 1070000 2834000 1296000
    UNITS METERS
    IMAGECOLOR 255 255 255
    IMAGETYPE PNG
    SIZE 2050 2050
    MAXSIZE 4096

    OUTPUTFORMAT
      NAME png
      DRIVER "AGG/PNG" # transparent PNGs require the AGG renderer
      MIMETYPE "image/png" # on some systems (BS) mapserver can not correlate the format parameter to this specification. this fixes this issue
      EXTENSION "png"
      IMAGEMODE RGBA
    END

    PROJECTION
        "init=epsg:2056"
    END

    WEB
        METADATA
            "wfs_title" "KbS Intern WFS"
            "wfs_onlineresource" "${MAPSERVER_URL}/?map=kbs_current&"
            "wfs_srs" "EPSG:2056"
            "wfs_enable_request" "*"

            "wms_title" "KbS Intern WMS"
            "wms_onlineresource" "${MAPSERVER_URL}/?map=kbs_current&"
            "wms_srs"            "EPSG:2056 "
            "ows_enable_request" "*"
            "ows_encoding"       "UTF-8"
            "wfs_encoding"       "UTF-8"
            "gml_encoding"       "UTF-8"
            "wms_feature_info_mime_type" "application/json"
            "wms_exceptions_format" "application/vnd.ogc.se_xml"
            "wms_abstract"       "Kataster belasteter Standorte" 
        END
    END

    LAYER
        NAME "current_all"
        TYPE POLYGON
        STATUS ON
        CONNECTIONTYPE POSTGIS
        CONNECTION "dbname='alma' host='db' port='5432' user='${MAPSERVER_POSTGRES_USER}' password='${MAPSERVER_POSTGRES_PASSWORD}'"
        DATA "wkb_geometry FROM alma_export.wfs_vflz_current_all_de_v USING UNIQUE vflz_id USING SRID=2056"

        METADATA
            "wfs_title" "KbS Current All"
            "wfs_srs" "EPSG:2056"
            "gml_include_items" "all"
            "gml_featureid" "vflz_id"
            "wfs_enable_request" "*"
        END

        PROJECTION
            "init=epsg:2056"
        END

        CLASS
            NAME "Default"
            STYLE
                COLOR [color_rgb]
                SIZE 10
                OUTLINECOLOR [color_rgb]
                WIDTH 4
                ANTIALIAS TRUE
            END
        END
    END

